import React, { useState, useEffect } from 'react';
import axios from 'axios';
import DashboardLayout from './DashboardLayout';

const WalletPage = () => {
  const user = JSON.parse(localStorage.getItem('vrx_user') || '{}');
  const [balance, setBalance] = useState(user.walletBalance || 0);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [addAmount, setAddAmount] = useState('');
  const [adding, setAdding] = useState(false);
  const [message, setMessage] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('upi');

  // Simulation Modal State
  const [showModal, setShowModal] = useState(false);
  const [targetAmount, setTargetAmount] = useState(0);

  // Card Inputs
  const [cardNumber, setCardNumber] = useState('');
  const [cardExpiry, setCardExpiry] = useState('');
  const [cardCVV, setCardCVV] = useState('');

  const fetchWallet = () => {
    if (!user._id) return;
    setLoading(true);
    axios.get(`http://localhost:5000/api/wallet/${user._id}`)
      .then(res => {
        setBalance(res.data.balance);
        setTransactions(res.data.transactions);

        // Sync local storage balance
        const u = JSON.parse(localStorage.getItem('vrx_user') || '{}');
        u.walletBalance = res.data.balance;
        localStorage.setItem('vrx_user', JSON.stringify(u));

        setLoading(false);
      }).catch(() => setLoading(false));
  };

  useEffect(() => { 
    fetchWallet(); 
  }, []);

  const triggerPaymentModal = (amount) => {
    const val = amount || parseInt(addAmount);
    if (!val || val <= 0) return;
    setTargetAmount(val);
    setShowModal(true);
  };

  const handleAddMoney = async () => {
    setAdding(true);
    try {
      const res = await axios.post(`http://localhost:5000/api/wallet/${user._id}/add`, { 
        amount: targetAmount, 
        paymentMethod,
        razorpayDetails: {
          orderId: "order_mock_" + Math.random().toString(36).substring(7),
          paymentId: "pay_mock_" + Math.random().toString(36).substring(7),
          signature: "sig_mock_" + Math.random().toString(36).substring(7)
        }
      });
      setBalance(res.data.balance);
      const u = JSON.parse(localStorage.getItem('vrx_user') || '{}');
      u.walletBalance = res.data.balance;
      localStorage.setItem('vrx_user', JSON.stringify(u));
      setAddAmount('');
      setMessage(`₹${targetAmount} added successfully! (Simulated Razorpay transaction)`);
      setShowModal(false);

      // Reset card inputs
      setCardNumber('');
      setCardExpiry('');
      setCardCVV('');

      setTimeout(() => setMessage(''), 4000);
      fetchWallet();
    } catch (err) {
      setMessage('Failed to add money');
    }
    setAdding(false);
  };

  // Get active security holds
  const activeHolds = transactions
    .filter(t => t.type === 'security_hold')
    .reduce((sum, hold) => {
      // Find if this hold has been refunded
      const isRefunded = transactions.some(r => r.type === 'deposit_refund' && r.bookingId === hold.bookingId);
      return isRefunded ? sum : sum + hold.amount;
    }, 0);

  return (
    <DashboardLayout activeTab="wallet">
      {message && <div className={`alert ${message.includes('success') ? 'alert-success' : 'alert-danger'} py-2 mb-4 text-center rounded-3 fw-bold`}>{message}</div>}

      <div className="row g-4">
        {/* Balance Card */}
        <div className="col-lg-5">
          <div className="rounded-4 shadow-sm overflow-hidden" style={{ background: 'linear-gradient(135deg, #0F172A, #1E293B)' }}>
            <div className="p-5 text-white">
              <div className="d-flex align-items-center gap-2 mb-3">
                <i className="fa-solid fa-wallet fs-4" style={{ color: '#06B6D4' }}></i>
                <span className="text-uppercase small fw-bold" style={{ letterSpacing: '2px', color: '#94A3B8' }}>Wallet Balance</span>
              </div>
              <h1 className="display-4 fw-bold mb-0">₹{balance.toLocaleString()}</h1>
              <p className="mt-2 mb-0" style={{ color: '#64748B' }}><i className="fa-solid fa-circle-check me-1" style={{ color: '#10B981' }}></i> Active Wallet</p>
            </div>

            <div style={{ background: 'rgba(255,255,255,0.05)', padding: '20px 30px' }}>
              <div className="d-flex justify-content-between text-white text-center">
                <div>
                  <small style={{ color: '#94A3B8' }}>Active Holds</small>
                  <br/>
                  <span className="fw-bold text-warning">₹{activeHolds}</span>
                </div>
                <div style={{ borderLeft: '1px solid rgba(255,255,255,0.1)', borderRight: '1px solid rgba(255,255,255,0.1)', padding: '0 15px' }}>
                  <small style={{ color: '#94A3B8' }}>Total Spent</small>
                  <br/>
                  <span className="fw-bold text-danger">₹{transactions.filter(t => t.type === 'ride_payment').reduce((a, t) => a + t.amount, 0)}</span>
                </div>
                <div>
                  <small style={{ color: '#94A3B8' }}>Deposited</small>
                  <br/>
                  <span className="fw-bold text-success">₹{transactions.filter(t => t.type === 'topup').reduce((a, t) => a + t.amount, 0)}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Add Money Form */}
          <div className="bg-white rounded-4 shadow-sm p-4 mt-4">
            <h5 className="fw-bold mb-3"><i className="fa-solid fa-plus-circle me-2 text-success"></i>Top up Credits</h5>
            <div className="d-flex gap-2 mb-3 flex-wrap">
              {[100, 200, 500, 1000, 2000].map(amt => (
                <button key={amt} className="btn btn-outline-dark rounded-pill fw-bold px-3" onClick={() => triggerPaymentModal(amt)}>
                  +₹{amt}
                </button>
              ))}
            </div>
            <div className="input-group mb-3">
              <span className="input-group-text bg-light border-0 fw-bold">₹</span>
              <input type="number" className="form-control p-3 bg-light border-0" placeholder="Enter custom amount" value={addAmount} onChange={e => setAddAmount(e.target.value)} />
              <button className="btn btn-primary-custom px-4" style={{ background: 'var(--primary)', borderColor: 'var(--primary)' }} onClick={() => triggerPaymentModal()} disabled={!addAmount}>
                Add
              </button>
            </div>
            <div className="d-flex gap-2">
              {[{ id: 'upi', icon: 'fa-mobile-screen', label: 'UPI QR Pay' }, { id: 'card', icon: 'fa-credit-card', label: 'Razorpay Card' }].map(m => (
                <button key={m.id} className={`btn flex-grow-1 rounded-3 p-2 ${paymentMethod === m.id ? 'btn-dark' : 'btn-outline-secondary'}`} onClick={() => setPaymentMethod(m.id)}>
                  <i className={`fa-solid ${m.icon} me-2`}></i>{m.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Transaction History */}
        <div className="col-lg-7">
          <div className="bg-white rounded-4 shadow-sm p-4">
            <h5 className="fw-bold mb-4"><i className="fa-solid fa-clock-rotate-left me-2 text-primary"></i>Campus Transaction Logs</h5>
            {loading ? (
              <div className="text-center p-4"><div className="spinner-border text-primary"></div></div>
            ) : transactions.length === 0 ? (
              <div className="text-center p-5">
                <i className="fa-solid fa-receipt fs-1 text-muted mb-3" style={{ opacity: 0.3 }}></i>
                <p className="text-muted">No transactions registered. Credit your wallet to start.</p>
              </div>
            ) : (
              <div className="d-flex flex-column gap-2" style={{ maxHeight: '480px', overflowY: 'auto' }}>
                {transactions.map((tx, i) => {
                  const isPositive = ['topup', 'deposit_refund'].includes(tx.type);
                  return (
                    <div key={tx._id || i} className="d-flex align-items-center gap-3 p-3 rounded-3" style={{ background: '#F8FAFC', transition: 'background 0.2s' }}
                      onMouseEnter={e => e.currentTarget.style.background = '#F1F5F9'}
                      onMouseLeave={e => e.currentTarget.style.background = '#F8FAFC'}>
                      <div style={{
                        width: '45px', height: '45px', borderRadius: '12px',
                        background: tx.type === 'topup' ? 'rgba(16,185,129,0.1)' : tx.type === 'deposit_refund' ? 'rgba(6,182,212,0.1)' : tx.type === 'security_hold' ? 'rgba(245,158,11,0.1)' : 'rgba(239,68,68,0.1)',
                        color: tx.type === 'topup' ? '#10B981' : tx.type === 'deposit_refund' ? '#06B6D4' : tx.type === 'security_hold' ? '#F59E0B' : '#EF4444',
                        display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '18px', flexShrink: 0
                      }}>
                        <i className={`fa-solid ${tx.type === 'topup' ? 'fa-arrow-down' : tx.type === 'deposit_refund' ? 'fa-rotate-left' : tx.type === 'security_hold' ? 'fa-lock' : 'fa-arrow-up'}`}></i>
                      </div>
                      <div className="flex-grow-1">
                        <h6 className="fw-bold mb-0">
                          {tx.description || (tx.type === 'topup' ? 'Wallet Deposit' : tx.type === 'security_hold' ? 'Security Hold' : tx.type === 'deposit_refund' ? 'Refund Release' : 'Ride Charges')}
                        </h6>
                        <small className="text-muted" style={{ fontSize: '11px' }}>
                          {new Date(tx.createdAt).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}
                          {tx.razorpayDetails?.paymentId && <span className="text-primary ms-1">({tx.razorpayDetails.paymentId})</span>}
                        </small>
                      </div>
                      <h5 className={`fw-bold m-0 ${isPositive ? 'text-success' : 'text-danger'}`}>
                        {isPositive ? '+' : '-'}₹{tx.amount}
                      </h5>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Payment Gateway Simulation Modal */}
      {showModal && (
        <div className="modal fade show" style={{ display: 'block', backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1050 }}>
          <div className="modal-dialog modal-dialog-centered">
            <div className="modal-content border-0 rounded-4 shadow-lg">
              <div className="modal-header border-0 bg-dark text-white rounded-top-4 p-4">
                <div className="d-flex align-items-center gap-2">
                  <i className="fa-solid fa-credit-card fs-4 text-warning"></i>
                  <div>
                    <h5 className="modal-title fw-bold">VehicleRentx Payment Gateway</h5>
                    <small className="text-white-50">Secure Razorpay Sandbox</small>
                  </div>
                </div>
                <button type="button" className="btn-close btn-close-white" onClick={() => setShowModal(false)}></button>
              </div>
              <div className="modal-body p-4">
                <div className="text-center mb-4">
                  <span className="text-muted small d-block">MERCHANT: VEHICLERENTX</span>
                  <h2 className="fw-bold text-dark">₹{targetAmount}</h2>
                </div>

                {paymentMethod === 'upi' ? (
                  <div className="text-center">
                    <p className="text-muted small mb-3">Scan standard dynamic UPI QR code to complete</p>
                    <div className="bg-light p-3 rounded-4 d-inline-block mb-3 border">
                      <div style={{ width: '150px', height: '150px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: '#fff', border: '5px solid #222' }}>
                        <i className="fa-solid fa-qrcode fs-1" style={{ fontSize: '100px' }}></i>
                        <span style={{ fontSize: '9px', fontWeight: '800', marginTop: '5px', letterSpacing: '1px' }}>UPI DYNAMIC</span>
                      </div>
                    </div>
                    <div className="alert alert-info py-2 small mb-3 text-start">
                      <i className="fa-solid fa-circle-info me-2"></i> Simulated UPI handler connects dynamically to wallet top-up logs.
                    </div>
                  </div>
                ) : (
                  <div>
                    <p className="text-muted small mb-3">Enter mock credentials for sandbox testing</p>
                    <div className="mb-3">
                      <label className="form-label small fw-bold text-muted">MOCK CREDIT CARD</label>
                      <input type="text" className="form-control bg-light border-0 p-3 rounded-3" placeholder="4111 2222 3333 4444" value={cardNumber} onChange={e => setCardNumber(e.target.value)} />
                    </div>
                    <div className="row">
                      <div className="col-6 mb-3">
                        <label className="form-label small fw-bold text-muted">EXPIRY</label>
                        <input type="text" className="form-control bg-light border-0 p-3 rounded-3" placeholder="12/28" value={cardExpiry} onChange={e => setCardExpiry(e.target.value)} />
                      </div>
                      <div className="col-6 mb-3">
                        <label className="form-label small fw-bold text-muted">CVV</label>
                        <input type="password" maxLength="3" className="form-control bg-light border-0 p-3 rounded-3" placeholder="123" value={cardCVV} onChange={e => setCardCVV(e.target.value)} />
                      </div>
                    </div>
                  </div>
                )}

                <button className="btn btn-primary w-100 py-3 rounded-pill mt-3 text-white fw-bold" style={{ background: 'var(--primary)' }} onClick={handleAddMoney} disabled={adding}>
                  {adding ? 'Processing...' : 'Authorize simulated success'}
                </button>
                <button type="button" className="btn btn-light w-100 py-2 rounded-pill mt-2" onClick={() => setShowModal(false)}>
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </DashboardLayout>
  );
};

export default WalletPage;
